import json
EP = {1: ('第一集', '守住', 'W01–W10。一位守将，一条每天不到一吨的通道：穿越规则与额度换算（每周净约 6.8 吨）；沙洲约 900 人、存粮半饷 6 周的家底；郑州黑户起步、日结与小队；卖掉最后的碎银和金器换口粮；止疫、种土豆、收缩防线到子城；望远镜、医疗包、仔猪鸡苗、光伏和对讲机。结论：口粮吃掉了几乎所有的钱。',
          ['沙洲战备推演（一）：守住', '每天只能带一吨，怎么救一座不到千人的孤城', '黑户守将的前十周：不饿死、不病死']),
      2: ('第二集', '强军', 'W11–W24。成品弩买不了，就用报废车的钢板弹簧造弩；民壮弩手制度让妇女和少年也能上城；车床、刺绳障碍带、冷轧钢板甲；侦察乌兰城，郑州暴雨救人；九十骑远袭 400 公里外的外族商城，夺回金银、救回 86 人；黑户零散卖金，引来打听。结论：本钱只能靠打，金子卖不出去才是常态。',
          ['沙洲战备推演（二）：强军', '废钢造弩、远袭乌兰城：孤城的第一笔本钱', '九十骑夜袭六千人的城：只夺仓库，不攻城']),
      3: ('第三集', '外交分化', 'W25–W38。治安机关安平署盘查登记、帮小忙、长期观察、第一次面谈、发现共同利益，仍不走官方渠道；东帐部秋季报复，分层防守扛住 1500 骑；东西两帐互疑，结好西帐、订互市之约；科研样品与检疫。结论：合作的基础不是信任，而是互相需要。',
          ['沙洲战备推演（三）：外交分化', '被看见以后：盘查、观察与第一次面谈', '扛住秋季报复，在东西两帐之间找到盟友']),
      4: ('第四集', '拓土', 'W39–W52。额度第一次成为瓶颈；样品交接与精炼厂合法回收金子；烽燧链连起五个村堡；办证、注册公司、合法采购抗生素和设备；先围后谈收复寿昌，治下人口过两千；一年前后对照、全年总账、风险与第二年展望：从"输血"到"种技术"。',
          ['沙洲战备推演（四）：拓土', '从一座孤城到一百五十公里的据点链', '一年之后：两千三百人、三座医馆和一条烽燧链'])}
o = ['# 沙洲战备推演（四集专题）\n\n本系列由 AI 生成：文稿与画面由 Claude 制作，配音为 Gemini TTS 合成（1.25 倍速）。故事为架空推演：沙洲、乌兰城、寿昌、东帐部 / 西帐部、安平署等均为虚构；人口、存粮、战利品等标【假设】的数字为推演采用的假设；价格是 2026 年郑州附近零售或二手市场的粗略估算（粮食约 2.6 元/kg、金价约 900 元/g、银价约 10 元/g、黑市卖金按六折），只用来比较量级；地图与现金曲线为示意。\n\n标签：穿越　架空历史　推演　孤城　守城　后勤　冷兵器　AI 生成\n']
for ep, (k, nm, bl, titles) in EP.items():
    TL = json.load(open(f'tl_e{ep}.json')); d = TL['total']; fn = f'沙洲战备推演_第{ep}集_{nm}'
    o.append(f'\n## {k} · {nm}（{int(d//60)}:{int(d%60):02d}）\n\n**标题候选**\n\n' + ''.join(f'{i+1}. {t}\n' for i, t in enumerate(titles)) + f'\n**文件**：`{fn}.mp4`　字幕：`{fn}.srt`　封面：`封面_第{ep}集_16x9.png` / `_4x3.png` / `_3x4.png`\n\n**简介**：{bl}\n\n**章节**\n\n')
    for s in TL['scenes']:
        t = 0 if s is TL['scenes'][0] else s['start']; o.append(f"{int(t//60):02d}:{int(t%60):02d} {s['title'].split(' ', 1)[1] if s['chapter'] else '片头'}\n")
o.append('\n## 来源\n\n- 推演底稿：《沙洲战备逐周推演》（第二版，2026-11-08）\n')
import os; os.makedirs('final', exist_ok=True)
open('final/标题与描述.md', 'w').write(''.join(o)); print('ok')
